function TrackingResults(p:{tracking:string;setTracking:(x:string)=>void;track:(x?:string)=>void;selected:Shipment|null;loading:boolean;setView:(x:any)=>void}){return <section className="tracking-page"><div className="tracking-page-head"><div><div className="tracking-breadcrumb">Home <span>/</span> Tracking</div><span className="eyebrow">Shipment tracking</span><h1>Shipment Tracking</h1></div><button className="secondary" onClick={()=>{window.setTimeout(()=>p.setView('track'),2000)}}>← Back to Home</button></div><div className="tracking-search"><div className="input-wrap"><Search size={20}/><input value={p.tracking} onChange={e=>p.setTracking(e.target.value)} onKeyDown={e=>e.key==='Enter'&&p.track()} placeholder="Tracking number"/></div><button className="primary track-action" onClick={()=>p.track()} disabled={p.loading}>{p.loading?'Tracking…':'Track Shipment'}</button></div>{p.selected?<Details shipment={p.selected}/>:<div className="empty"><Package size={38}/><h2>Shipment not found</h2><p>Check the tracking number and try again.</p></div>}</section>}

function ShipmentJourney({status,events}:{status:string;events:Event[]}){const current=(status||'order placed').toLowerCase();let active=0;if(/deliver(ed|y complete)/.test(current))active=5;else if(/custom|clearance hold|on hold/.test(current))active=4;else if(/out for delivery/.test(current))active=3;else if(/transit|shipped|departed|arrived at facility/.test(current))active=2;else if(/pick.?up|collected/.test(current))active=1;else if(/order|created|pending|processing|label/.test(current))active=0;const stages=[{label:'Order placed',hint:'Shipment details received'},{label:'Picked up',hint:'Parcel collected'},{label:'In transit',hint:'Moving through the network'},{label:'Out for delivery',hint:'Courier is on the way'},{label:'Customs hold',hint:'Awaiting customs clearance',optional:true},{label:'Delivered',hint:'Shipment successfully delivered'}];const held=/custom|clearance hold|on hold/.test(current);return <section className="journey-card" aria-label="Shipment journey"><div className="journey-heading"><div><span className="muted">DELIVERY JOURNEY</span><h3>Track your shipment</h3></div><span className={'journey-current '+(held?'journey-held':'')}>{held?'Customs hold':status||'Order placed'}</span></div><div className="journey-steps">{stages.map((stage,i)=>{const done=i<active||(active===5&&i===5);const now=i===active;return <div className={'journey-step '+(done?'is-done ':'')+(now?'is-current ':'')+(held&&i===4?'is-held ':'')+(stage.optional?'is-optional':'')} key={stage.label}><div className="journey-marker">{done?<CheckCircle2 size={18}/>:i+1}</div><div className="journey-step-copy"><strong>{stage.label}</strong><span>{stage.hint}</span>{stage.optional&&<small>May not apply to every shipment</small>}</div></div>})}</div>{held&&<div className="journey-alert"><Clock3 size={17}/><div><strong>Customs clearance hold</strong><span>Your shipment is temporarily awaiting customs review. Tracking will update when it is released.</span></div></div>}</section>}
function Details({shipment:s}:{shipment:Shipment}){const extra=s as any;const progress=Math.min(100,Math.max(8,Math.round((s.events.filter(e=>e.done).length/Math.max(s.events.length,1))*100)));const senderName=extra.senderName||s.customerName||'Not provided';const senderPhone=extra.senderPhone||'';const senderEmail=extra.senderEmail||s.customerEmail||'';const receiverName=extra.receiverName||s.customerName||'Not provided';const receiverPhone=extra.receiverPhone||'';const receiverEmail=extra.receiverEmail||'';const shippedDate=extra.shippedDate||extra.shipDate||'';return <><style>{`.shipment-card .journey-card{display:block!important;margin:24px 0!important;padding:22px 20px!important;border:1px solid #d7e3ef!important;border-radius:16px!important;background:linear-gradient(180deg,#fff 0%,#f8fbff 100%)!important;box-shadow:0 8px 24px rgba(20,43,64,.08)!important;overflow:visible!important}.shipment-card .journey-heading{display:flex!important;flex-direction:row!important;justify-content:space-between!important;align-items:center!important;gap:12px!important;margin-bottom:25px!important}.shipment-card .journey-heading h3{font-size:20px!important;margin:5px 0 0!important;color:#142b40!important}.shipment-card .journey-current{font-size:12px!important;padding:8px 12px!important;border-radius:999px!important;background:#e5f7ed!important;color:#166534!important;white-space:normal!important}.shipment-card .journey-steps{display:grid!important;grid-template-columns:repeat(6,minmax(0,1fr))!important;gap:0!important;overflow:visible!important;position:relative!important;padding:0!important}.shipment-card .journey-step{display:flex!important;flex-direction:column!important;align-items:center!important;text-align:center!important;min-width:0!important;position:relative!important;padding:0 2px!important}.shipment-card .journey-step:before{content:''!important;display:block!important;position:absolute!important;top:17px!important;left:0!important;right:0!important;width:auto!important;height:4px!important;background:#dbe4ee!important;z-index:0!important}.shipment-card .journey-step:first-child:before{left:50%!important}.shipment-card .journey-step:last-child:before{right:50%!important}.shipment-card .journey-marker{display:flex!important;align-items:center!important;justify-content:center!important;position:relative!important;z-index:1!important;width:36px!important;height:36px!important;min-width:36px!important;margin:0 auto 11px!important;border:2px solid #2563eb!important;border-radius:50%!important;background:#dbeafe!important;color:#1d4ed8!important;font-size:13px!important;font-weight:800!important;box-sizing:border-box!important}.shipment-card .journey-step:nth-child(2) .journey-marker{border-color:#0891b2!important;background:#cffafe!important;color:#0e7490!important}.shipment-card .journey-step:nth-child(3) .journey-marker{border-color:#7c3aed!important;background:#ede9fe!important;color:#6d28d9!important}.shipment-card .journey-step:nth-child(4) .journey-marker{border-color:#ea580c!important;background:#ffedd5!important;color:#c2410c!important}.shipment-card .journey-step:nth-child(5) .journey-marker{border-color:#d97706!important;background:#fef3c7!important;color:#92400e!important}.shipment-card .journey-step:nth-child(6) .journey-marker{border-color:#16a34a!important;background:#dcfce7!important;color:#15803d!important}.shipment-card .journey-step.is-done .journey-marker,.shipment-card .journey-step.is-current .journey-marker{background:#15803d!important;border-color:#15803d!important;color:#fff!important}.shipment-card .journey-step.is-done:before,.shipment-card .journey-step.is-current:before{background:#15803d!important}.shipment-card .journey-step.is-held .journey-marker{background:#fff2d7!important;border-color:#d97706!important;color:#945b00!important}.shipment-card .journey-step-copy{display:flex!important;flex-direction:column!important;align-items:center!important;gap:4px!important;padding:0 2px!important;min-width:0!important}.shipment-card .journey-step-copy strong{display:block!important;font-size:12px!important;line-height:1.25!important;color:#1e293b!important;overflow-wrap:anywhere!important}.shipment-card .journey-step-copy span,.shipment-card .journey-step-copy small{display:block!important;font-size:10px!important;line-height:1.35!important;color:#64748b!important}.shipment-card .journey-step-copy small{color:#8a6b32!important}.shipment-card .journey-alert{display:flex!important;gap:10px!important;align-items:flex-start!important;margin-top:20px!important;padding:13px 15px!important;border:1px solid #f3d28d!important;border-radius:12px!important;background:#fffbeb!important;color:#92400e!important}.shipment-card .journey-alert div{display:flex!important;flex-direction:column!important;gap:4px!important}.shipment-card .journey-alert span{font-size:13px!important;line-height:1.5!important;color:#78591f!important}@media(max-width:760px){.shipment-card .journey-card{padding:16px 9px!important;margin:18px 0!important}.shipment-card .journey-heading{gap:6px!important;margin-bottom:19px!important}.shipment-card .journey-heading h3{font-size:17px!important}.shipment-card .journey-current{font-size:10px!important;padding:6px 8px!important;max-width:48%!important;text-align:center!important}.shipment-card .journey-steps{grid-template-columns:repeat(6,minmax(0,1fr))!important;gap:0!important}.shipment-card .journey-step{padding:0 1px!important}.shipment-card .journey-step:before{top:13px!important;height:3px!important}.shipment-card .journey-marker{width:27px!important;height:27px!important;min-width:27px!important;margin-bottom:8px!important;font-size:10px!important}.shipment-card .journey-marker svg{width:13px!important;height:13px!important}.shipment-card .journey-step-copy{gap:2px!important}.shipment-card .journey-step-copy strong{font-size:8px!important;line-height:1.2!important;overflow-wrap:anywhere!important}.shipment-card .journey-step-copy span,.shipment-card .journey-step-copy small{display:none!important}}`}</style><div className="shipment-card reference-style"><div className="tracking-banner"><div><div className="banner-label"><Package size={15}/> Tracking Number</div><div className="banner-number">{s.tracking}</div></div><div className="banner-right"><Status value={s.status}/><span>Last Updated: {s.lastUpdated||'Recently'}</span></div></div><div className="info-strip"><Info label="Sender Information" value={[senderName,s.origin,senderPhone,senderEmail].filter(Boolean).join(' · ')}/><Info label="Receiver Information" value={[receiverName,s.destination,receiverPhone,receiverEmail].filter(Boolean).join(' · ')}/><Info label="Shipment Details" value={[s.weight,s.shippingMethod,s.product,s.quantity?'Quantity: '+s.quantity:'',s.reference?'Reference: '+s.reference:'',shippedDate?'Shipped: '+shippedDate:''].filter(Boolean).join(' · ')||'Shipment in transit'}/><Info label="Status Information" value={[s.status||'Processing',s.currentLocation||s.origin,s.eta?'Estimated delivery: '+s.eta:''].filter(Boolean).join(' · ')}/></div><div className="progress-wrap"><div className="progress-meta"><span>Shipment progress</span><strong>{progress}%</strong></div><div className="progress"><div style={{width:progress+'%'}}/></div></div><ShipmentJourney status={s.status} events={s.events}/><RouteMap shipment={s}/>{s.itemImages?.length?<div className="item-images"><div className="item-images-head"><span className="muted">ITEM PHOTOS</span><h3>Package contents</h3></div><div className="item-images-grid">{s.itemImages.map((src,i)=><a href={src} target="_blank" rel="noreferrer" key={i}><img src={src} alt={s.product+" image "+(i+1)}/></a>)}</div></div>:null}<div className="history-head"><div><span className="muted">PROGRESS</span><h3>Shipment History</h3></div><span className="history-status">{s.status}</span></div><div className="timeline">{s.events.map((e,i)=><div className="event" key={i}><div className={'dot '+(e.done?'done':'')}>{e.done?<CheckCircle2 size={15}/>:<Clock3 size={15}/>}</div><div><strong>{e.title}</strong><span>{e.location}</span><small>{e.time}</small></div></div>)}</div>{s.deliveryInstructions&&<div className="info-panel"><strong>Delivery instructions</strong><span>{s.deliveryInstructions}</span></div>}{s.proofOfDelivery&&<div className="info-panel"><strong>Proof of delivery</strong><span>{s.proofOfDelivery}</span></div>}{s.documents?.length&&<div className="docs"><h3>Documents</h3>{s.documents.map(d=><a key={d.name} href={d.url} target="_blank" rel="noreferrer">{d.name} ↗</a>)}</div>}<PublicFreightNote shipment={s}/></div></> }
function PublicFreightNote(props:{shipment:Shipment}){
 const s=props.shipment;
 const extra=s as any;
 const noteNumber='FN-'+String(s.tracking||s.id||'SHIPMENT').replace(/[^a-z0-9]/gi,'').toUpperCase();
 const rows:[string,any][]=[['Tracking number',s.tracking],['Reference',s.reference],['Shipper / sender',extra.senderName||s.customerName],['Receiver',extra.receiverName||s.customerName],['Origin',s.origin],['Destination',s.destination],['Carrier',s.carrier],['Shipping method',s.shippingMethod],['Description of goods',s.product],['Quantity',s.quantity],['Weight',s.weight],['Dimensions',s.dimensions],['Current location',s.currentLocation||s.origin],['Shipment status',s.status],['Estimated delivery',s.eta],['Delivery instructions',s.deliveryInstructions]];
 const printNote=()=>{
  const safe=(v:any)=>String(v||'—').replace(/[&<>"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]!));
  const w=window.open('','_blank','width=900,height=700');if(!w)return;
  w.document.write('<!doctype html><html><head><title>'+safe(noteNumber)+'</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font:14px Arial,sans-serif;color:#182b3a;margin:32px}header{background:#102b43;color:white;padding:24px}h1{margin:0 0 8px;font-size:25px}p{line-height:1.5}.tag{font-size:11px;letter-spacing:2px;text-transform:uppercase}table{width:100%;border-collapse:collapse;margin-top:22px}th,td{text-align:left;border:1px solid #d7e0e8;padding:11px;vertical-align:top}th{background:#f0f5f8;width:24%}.disclaimer{margin-top:24px;color:#596879;font-size:12px}@media print{body{margin:12mm}}</style></head><body><header><div class="tag">Parcel Shipment · Shipment document</div><h1>Freight Note</h1><div>'+safe(noteNumber)+'</div></header><p>This document summarizes the shipment details available in the tracking record.</p><table>'+rows.map(([k,v])=>'<tr><th>'+safe(k)+'</th><td>'+safe(v)+'</td></tr>').join('')+'</table><p class="disclaimer">This freight note is a shipment summary generated from the tracking record. It is not a bill of lading, customs declaration, invoice, or proof of payment.</p><script>window.onload=()=>window.print()<\\/script></body></html>');
  w.document.close();
 };
 return <section className="public-freight-inline" aria-label="Freight note"><div className="public-freight-inline-head"><div className="public-freight-inline-icon">FN</div><div><span className="public-freight-kicker">SHIPMENT DOCUMENT</span><h2>Freight Note</h2><p>Shipment summary · {noteNumber}</p></div><button className="primary public-freight-print" type="button" onClick={printNote}>Print / Save as PDF</button></div><div className="public-freight-paper"><div className="public-freight-brand">PARCEL SHIPMENT<span>FREIGHT NOTE</span></div><div className="public-freight-number"><span>Freight note number</span><strong>{noteNumber}</strong></div><div className="public-freight-grid">{rows.map(([label,value])=><div className="public-freight-field" key={label}><span>{label}</span><strong>{value||'—'}</strong></div>)}</div><p className="public-freight-disclaimer">This freight note is a shipment summary generated from the tracking record. It is not a bill of lading, customs declaration, invoice, or proof of payment.</p></div></section>;
}

function Account({me,shipments,signIn,signUp,onTrack,refresh}:{me:Me|null;shipments:Shipment[];signIn:()=>void;signUp:()=>void;onTrack:(s:string)=>void;refresh:()=>void}){
 if(!me)return <section className="content account-login"><div className="empty"><User size={40}/><h2>Your customer account</h2><p>Create an account to save your tracking number and view your shipment anytime without entering the tracking code again.</p><div className="account-actions"><button className="primary" onClick={signUp}>Create a free account</button><button className="secondary" onClick={signIn}>Sign in</button></div></div></section>;
 return <section className="content"><div className="page-title"><div><div className="eyebrow">Customer account</div><h1>My Account</h1><p>@{me.username} · {me.email}</p></div><button className="secondary" onClick={refresh}><RefreshCw size={15}/> Refresh</button></div>
 <div className="account-profile-grid"><div className="account-profile-card"><span className="eyebrow">Personal details</span><h3>{[me.firstName,me.middleName,me.lastName].filter(Boolean).join(' ')}</h3><p>Username: @{me.username}</p><p>Email: {me.email}</p><p>Phone: {me.phone||'—'}</p></div><div className="account-profile-card"><span className="eyebrow">Address</span><h3>{me.country||'Country not set'}</h3><p>{[me.address,me.city,me.state,me.postalCode].filter(Boolean).join(', ')||'No address added.'}</p></div></div>
 <div className="page-title account-section-title"><div><div className="eyebrow">Saved shipments</div><h2>My Shipments</h2><p>Your saved tracking numbers appear here automatically.</p></div></div>
 {shipments.length?<div className="shipment-list">{shipments.map(s=><button className="shipment-row" key={s.tracking} onClick={()=>onTrack(s.tracking)}><div className="mini-icon"><Package size={18}/></div><div><strong>{s.product}</strong><span>{s.tracking} · {s.destination}</span></div><Status value={s.status}/><ChevronRight size={17}/></button>)}</div>:<div className="empty"><Package size={38}/><h2>No shipments linked yet</h2><p>Your account does not have a shipment linked to it yet.</p></div>}</section>
}
function AuthPages({mode,setMode,close,onAuthenticated}:{mode:'login'|'register';setMode:(mode:'none'|'login'|'register')=>void;close:()=>void;onAuthenticated:(token:string,user:Me)=>Promise<void>}){
 const [step,setStep]=useState(1); const [busy,setBusy]=useState(false); const [error,setError]=useState('');
 const [form,setForm]=useState<any>({firstName:'',lastName:'',middleName:'',username:'',email:'',phone:'',country:'',address:'',city:'',state:'',postalCode:'',password:'',confirmPassword:'',trackingNumber:'',login:'',loginPassword:''});
 const set=(k:string,v:string)=>setForm((x:any)=>({...x,[k]:v}));
 const submit=async()=>{setError('');setBusy(true);try{
   if(mode==='login'){const r=await api.post('/api/auth/login',{usernameOrEmail:form.login,password:form.loginPassword});await onAuthenticated(r.data.token,r.data.user);return}
   const r=await api.post('/api/auth/register',form);await onAuthenticated(r.data.token,r.data.user);
 }catch(e:any){setError(e?.message||'Could not complete this request.')}finally{setBusy(false)}};
 const next=()=>{setError('');if(step===1&&!form.firstName.trim()||step===1&&!form.lastName.trim()||step===1&&!form.username.trim()){setError('First name, last name and username are required.');return}if(step===2&&!form.email.trim()||step===2&&!form.phone.trim()||step===2&&!form.country.trim()){setError('Email, phone number and country are required.');return}if(step===3&&(!form.password||form.password.length<8||form.password!==form.confirmPassword)){setError(form.password.length<8?'Password must be at least 8 characters.':'Passwords must match.');return}if(step===4&&!form.trackingNumber.trim()){setError('Tracking number is required.');return}setStep(step+1)};
 if(mode==='login')return <div className="auth-overlay"><div className="auth-card"><button className="auth-close" onClick={close}>×</button><div className="eyebrow">Customer account · Sign in</div><h1>Welcome back</h1><p className="auth-subtitle">Sign in to open your saved shipment account.</p>{error&&<div className="auth-error">{error}</div>}<label>Username or Email<input value={form.login} onChange={e=>set('login',e.target.value)} placeholder="@johnsmith123 or you@example.com"/></label><label>Password<input type="password" value={form.loginPassword} onChange={e=>set('loginPassword',e.target.value)} placeholder="Your password"/></label><button className="primary auth-submit" disabled={busy} onClick={()=>void submit()}>{busy?'Signing in…':'Sign in'}</button><div className="auth-footer">Don't have an account? <button onClick={()=>{setStep(1);setError('');setMode('register')}}>Create a free account</button></div></div></div>;
 const titles=['Personal information','Contact & address','Account security','Shipment linking'];
 const subtitles=['Tell us who you are.','How we can reach you.','Protect your account.','Connect your tracking number to your account.'];
 return <div className="auth-overlay"><div className="auth-card auth-multi"><button className="auth-close" onClick={close}>×</button><div className="eyebrow">Customer account · Page {step} of 4</div><h1>{titles[step-1]}</h1><p className="auth-subtitle">{subtitles[step-1]}</p><div className="auth-progress"><span style={{width:(step*25)+'%'}}/></div>{error&&<div className="auth-error">{error}</div>}
 {step===1&&<div className="auth-fields"><label>First Name *<input value={form.firstName} onChange={e=>set('firstName',e.target.value)} placeholder="John"/></label><label>Last Name *<input value={form.lastName} onChange={e=>set('lastName',e.target.value)} placeholder="Smith"/></label><label>Middle Name<input value={form.middleName} onChange={e=>set('middleName',e.target.value)} placeholder="David"/></label><label>Username *<input value={form.username} onChange={e=>set('username',e.target.value.replace(/^@/,''))} placeholder="@johnsmith123"/></label></div>}
 {step===2&&<div className="auth-fields"><label>Email Address *<input type="email" value={form.email} onChange={e=>set('email',e.target.value)} placeholder="john@example.com"/></label><label>Phone Number *<input value={form.phone} onChange={e=>set('phone',e.target.value)} placeholder="+1 555 000 0000"/></label><label>Country *<input value={form.country} onChange={e=>set('country',e.target.value)} placeholder="Canada"/></label><label>Street Address<input value={form.address} onChange={e=>set('address',e.target.value)} placeholder="123 Main Street"/></label><label>City<input value={form.city} onChange={e=>set('city',e.target.value)} placeholder="Toronto"/></label><label>State / Province<input value={form.state} onChange={e=>set('state',e.target.value)} placeholder="Ontario"/></label><label>Postal / ZIP Code<input value={form.postalCode} onChange={e=>set('postalCode',e.target.value)} placeholder="A1A 1A1"/></label></div>}
 {step===3&&<div className="auth-fields"><label>Password *<input type="password" value={form.password} onChange={e=>set('password',e.target.value)} placeholder="At least 8 characters"/></label><label>Confirm Password *<input type="password" value={form.confirmPassword} onChange={e=>set('confirmPassword',e.target.value)} placeholder="Enter your password again"/></label><div className="auth-note">Use a password you can remember. Your password is securely stored and is not shown in your account.</div></div>}
 {step===4&&<div className="auth-fields"><label>Tracking Number *<input value={form.trackingNumber} onChange={e=>set('trackingNumber',e.target.value.toUpperCase())} placeholder="PT10004"/></label><div className="auth-note">This connects your shipment to your new account. After registration, you can open <strong>My Shipments</strong> anytime without entering this tracking number again.</div></div>}
 <div className="auth-actions">{step>1?<button className="secondary" onClick={()=>setStep(step-1)}>Back</button>:<button className="secondary" onClick={close}>Cancel</button>}{step<4?<button className="primary" onClick={next}>Continue</button>:<button className="primary" disabled={busy} onClick={()=>void submit()}>{busy?'Creating account…':'Create account'}</button>}</div>
 <div className="auth-footer">Already have an account? <button onClick={()=>{setMode('login');setStep(1);setError('')}}>Sign in</button></div>
 </div></div>
}
function AdminLogin({onLogin}:{onLogin:(token:string)=>void}){const [password,setPassword]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async()=>{setBusy(true);setError('');try{const r=await api.post('/api/admin/login',{password});onLogin(r.data.token)}catch(e:any){setError(e?.message||'Incorrect admin password.')}finally{setBusy(false)}};return <section className="content"><div className="auth-card" style={{maxWidth:520,margin:'80px auto'}}><div className="eyebrow">Parcel Shipment · Admin</div><h1>Admin access</h1><p className="auth-subtitle">Sign in here to create and manage tracking numbers. The admin panel is now part of this website.</p>{error&&<div className="auth-error">{error}</div>}<label>Admin password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>e.key==='Enter'&&void submit()} placeholder="Enter admin password"/></label><button className="primary auth-submit" disabled={busy||!password} onClick={()=>void submit()}>{busy?'Signing in…':'Open admin panel'}</button></div></section>}
function Admin({shipments,filter,setFilter,refresh,edit,create}:{shipments:Shipment[];filter:string;setFilter:(s:string)=>void;refresh:()=>void;edit:(s:Shipment)=>void;create:()=>void}){const counts=shipments.reduce((a,s)=>({...a,[s.status]:(a[s.status]||0)+1}),{} as Record<string,number>);return <section className="content admin"><div className="page-title"><div><div className="eyebrow">Parcel Shipment · Admin</div><h1>Create tracking numbers</h1><p>Enter the customer's name, product and destination country, then manage the tracking status.</p></div><div className="page-actions"><button className="secondary" onClick={refresh}><RefreshCw size={15}/> Refresh</button><button className="primary" onClick={create}><Plus size={16}/> New tracking</button><button className="secondary" onClick={()=>{sessionStorage.removeItem('parceltrack_admin_token');window.location.hash='';window.location.reload()}}>Sign out admin</button></div></div><div className="stat-grid"><Stat label="Total" value={shipments.length}/><Stat label="In transit" value={counts['In transit']||0}/><Stat label="Out for delivery" value={counts['Out for delivery']||0}/><Stat label="Delivered" value={counts.Delivered||0}/></div><div className="filters">{STATUSES.map(x=><button className={filter===x?'active':''} key={x} onClick={()=>setFilter(x)}>{x}</button>)}</div><div className="table">{shipments.map(s=><div className="row" key={s.tracking}><div><strong>{s.tracking}</strong><span>{s.customerName||'No name'} · {s.product}</span></div><Status value={s.status}/><div><span>{s.country||s.destination}</span><small>ETA {s.eta}</small></div><div className="row-actions"><button onClick={()=>edit(s)}><Pencil size={15}/></button><button onClick={async()=>{if(confirm('Delete '+s.tracking+'?')){await api.delete('/api/admin/shipments/'+s.id);refresh()}}}><Trash2 size={15}/></button></div></div>)}</div></section>}
function Editor({shipment,close,saved,setError}:{shipment:Shipment|null;close:()=>void;saved:()=>void;setError:(s:string)=>void}){const [form,setForm]=useState<any>(shipment?{...shipment,tracking:shipment.tracking||'',product:shipment.product||'',itemImages:(shipment as any).itemImages||[]}:{tracking:'',customerName:'',senderName:'',senderPhone:'',senderEmail:'',receiverName:'',receiverPhone:'',receiverEmail:'',shippedDate:'',product:'',country:'',quantity:1,status:'Order received',eta:'',origin:'',destination:'',carrier:'Parcel Shipment',shippingMethod:'Standard',weight:'',dimensions:'',reference:'',customerEmail:'',currentLocation:'',deliveryInstructions:'',itemImages:[],events:[]});const [saving,setSaving]=useState(false);const [imageBusy,setImageBusy]=useState(false);const set=(k:string,v:any)=>setForm((x:any)=>({...x,[k]:v}));const addImages=async(files:FileList|null)=>{if(!files?.length)return;setImageBusy(true);try{const added=await Promise.all(Array.from(files).slice(0,6).map(file=>new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)})));set('itemImages',[...(form.itemImages||[]),...added])}catch{setError('Could not read one of the images.')}finally{setImageBusy(false)}};const save=async()=>{if(!form.tracking||!form.customerName||!form.product||!form.origin||!form.destination){setError('Please complete all required fields: customer name, product, tracking number, origin and destination.');return}setSaving(true);try{const payload:any={...form,trackingNumber:String(form.tracking).trim().toUpperCase(),itemDescription:form.product,packageDimensions:form.dimensions,currentLatitude:form.latitude,currentLongitude:form.longitude};delete payload.tracking;delete payload.product;delete payload.dimensions;delete payload.latitude;delete payload.longitude;if(shipment?.id)await api.put('/api/admin/shipments/'+shipment.id,payload);else await api.post('/api/admin/shipments',payload);saved()}catch(e:any){setError(e?.message||'Could not save shipment.')}finally{setSaving(false)}};return <div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><div className="eyebrow">Private tracking record</div><h2>{shipment?'Edit tracking':'Create tracking number'}</h2></div><button onClick={close}><X/></button></div><div className="form-grid"><label>Customer name<input value={form.customerName||''} onChange={e=>set('customerName',e.target.value)} placeholder="Full name"/></label><label>Sender name<input value={form.senderName||''} onChange={e=>set('senderName',e.target.value)} placeholder="Sender full name"/></label><label>Sender phone<input value={form.senderPhone||''} onChange={e=>set('senderPhone',e.target.value)} placeholder="Phone number"/></label><label>Sender email<input type="email" value={form.senderEmail||''} onChange={e=>set('senderEmail',e.target.value)} placeholder="Email address"/></label><label>Receiver name<input value={form.receiverName||''} onChange={e=>set('receiverName',e.target.value)} placeholder="Receiver full name"/></label><label>Receiver phone<input value={form.receiverPhone||''} onChange={e=>set('receiverPhone',e.target.value)} placeholder="Phone number"/></label><label>Receiver email<input type="email" value={form.receiverEmail||''} onChange={e=>set('receiverEmail',e.target.value)} placeholder="Email address"/></label><label>Shipped date<input type="date" value={form.shippedDate||''} onChange={e=>set('shippedDate',e.target.value)}/></label><label>Product<input value={form.product||''} onChange={e=>set('product',e.target.value)} placeholder="Product name"/></label><label>Destination country<input value={form.country||''} onChange={e=>set('country',e.target.value)} placeholder="Country"/></label><label>Tracking number<input value={form.tracking||''} onChange={e=>set('tracking',e.target.value.toUpperCase())} placeholder="PT10004"/></label><label>Quantity<input type="number" min="1" value={form.quantity??1} onChange={e=>set('quantity',Number(e.target.value)||1)}/></label><label>Estimated delivery<input type="date" value={form.eta||''} onChange={e=>set('eta',e.target.value)}/></label><label>Origin<input value={form.origin||''} onChange={e=>set('origin',e.target.value)}/></label><label>Destination<input value={form.destination||''} onChange={e=>set('destination',e.target.value)}/></label><label>Carrier<input value={form.carrier||''} onChange={e=>set('carrier',e.target.value)}/></label><label>Shipping method<input value={form.shippingMethod||''} onChange={e=>set('shippingMethod',e.target.value)}/></label><label>Package weight<input value={form.weight||''} onChange={e=>set('weight',e.target.value)}/></label><label>Package dimensions<input value={form.dimensions||''} onChange={e=>set('dimensions',e.target.value)}/></label><label>Order/reference number<input value={form.reference||''} onChange={e=>set('reference',e.target.value)}/></label><label>Customer email<input type="email" value={form.customerEmail||''} onChange={e=>set('customerEmail',e.target.value)}/></label><label>Current location<input value={form.currentLocation||''} onChange={e=>set('currentLocation',e.target.value)}/></label><label>Status<select value={form.status||'Order received'} onChange={e=>set('status',e.target.value)}>{STATUSES.slice(1).map(s=><option key={s}>{s}</option>)}</select></label><label>Current latitude<input type="number" step="any" value={form.latitude??form.currentLatitude??''} onChange={e=>set('latitude',e.target.value===''?undefined:Number(e.target.value))} placeholder="e.g. 43.6532"/></label><label>Current longitude<input type="number" step="any" value={form.longitude??form.currentLongitude??''} onChange={e=>set('longitude',e.target.value===''?undefined:Number(e.target.value))} placeholder="e.g. -79.3832"/></label><label className="image-upload-field">Item images<input type="file" accept="image/*" multiple onChange={e=>addImages(e.target.files)}/><small>{imageBusy?'Reading images…':'Add up to 6 photos of the item.'}</small></label>{form.itemImages?.length?<div className="image-preview-grid">{form.itemImages.map((src:string,i:number)=><div key={i}><img src={src} alt="Item preview"/><button type="button" onClick={()=>set('itemImages',form.itemImages.filter((_:string,j:number)=>j!==i))}><X size={13}/></button></div>)}</div>:null}<label className="wide-field">Delivery instructions<textarea value={form.deliveryInstructions||''} onChange={e=>set('deliveryInstructions',e.target.value)} placeholder="Optional delivery instructions"/></label></div><div className="modal-actions"><button className="secondary" onClick={close}>Cancel</button><button className="primary" onClick={save} disabled={saving}>{saving?'Saving…':shipment?'Save changes':'Create tracking'}</button></div></div></div>}
function Support({me,setError,setNotice}:{me:Me|null;setError:(s:string)=>void;setNotice:(s:string)=>void}){const [subject,setSubject]=useState(''),[message,setMessage]=useState(''),[sending,setSending]=useState(false);const send=async()=>{if(!me){setError('Please sign in before opening a support ticket.');return}if(!subject||!message){setError('Please enter a subject and message.');return}setSending(true);try{await api.post('/api/support/tickets',{subject,message});setSubject('');setMessage('');setNotice('Support ticket submitted.')}catch(e:any){setError(e?.message||'Could not submit ticket.')}finally{setSending(false)}};return <section className="content"><div className="page-title"><div><div className="eyebrow">Customer support</div><h1>How can we help?</h1><p>Report delivery problems, ask about a shipment or request assistance.</p></div></div><div className="support-grid"><div className="support-card"><Headphones size={24}/><h3>Support ticket</h3><p>Chat directly with the Parcel Shipment support team.</p><button className="primary" onClick={openSupportChat}>Open customer support chat</button><label>Subject<input value={subject} onChange={e=>setSubject(e.target.value)} placeholder="What do you need help with?"/></label><label>Message<textarea value={message} onChange={e=>setMessage(e.target.value)} placeholder="Tell us what happened…"/></label><button className="primary" onClick={send} disabled={sending}>{sending?'Sending…':'Submit ticket'}</button></div><div className="support-card"><ShieldCheck size={24}/><h3>Common help</h3><p><strong>Tracking</strong><br/>Use the tracking number provided by the sender or store.</p><p><strong>Delivery delay</strong><br/>Check the latest event and current location before contacting support.</p><p><strong>Delivery problem</strong><br/>Include your tracking number and a short description in your ticket.</p></div></div></section>}
const Status=({value}:{value:string})=><span className={'status '+value.toLowerCase().replaceAll(' ','-')}>{value}</span>;
const Info=({label,value}:{label:string;value:string})=><div><span>{label}</span><strong>{value||'—'}</strong></div>;
const Feature=({icon,title,text}:{icon:any;title:string;text:string})=><div className="feature"><span>{icon}</span><div><strong>{title}</strong><p>{text}</p></div></div>;
const Stat=({label,value}:{label:string;value:number})=><div className="stat"><span>{label}</span><strong>{value}</strong></div>;
function RouteMap({shipment:s}:{shipment:Shipment}){const current=s.currentLocation||s.origin;const hasCoords=Number.isFinite(Number(s.latitude))&&Number.isFinite(Number(s.longitude));const lat=Number(s.latitude),lon=Number(s.longitude);const delta=.08;const mapUrl=hasCoords?'https://www.openstreetmap.org/export/embed.html?bbox='+(lon-delta)+'%2C'+(lat-delta)+'%2C'+(lon+delta)+'%2C'+(lat+delta)+'&layer=mapnik&marker='+lat+'%2C'+lon:'';return <div className="route-map"><div className="route-map-head"><div><span className="muted">LIVE ROUTE</span><strong>Package location</strong></div><span className="route-live"><i/> {hasCoords?(s.status==='Delivered'?'Delivered':'Location available'):'Location pending'}</span></div>{hasCoords?<div className="live-map"><iframe title="Exact package location map" src={mapUrl} loading="lazy"/><div className="map-location"><MapPin size={15}/> {current} · {lat.toFixed(5)}, {lon.toFixed(5)}</div></div>:<ShipmentGlobe origin={s.origin} destination={s.destination} current={current} status={s.status}/>} <div className="route-map-head"><div><span className="muted">LIVE ROUTE</span><strong>Package movement</strong></div><span className="route-live"><i/> {s.status==='Delivered'?'Delivered':'Moving'}</span></div><div className="route-track"><div className="country-node"><div className="country-pin"><Truck size={16}/></div><strong>{s.origin}</strong><span>Origin</span></div><div className="route-path"><div className="route-line"/><div className="moving-package"><Package size={17}/></div><span className="route-current">Currently: {current}</span></div><div className="country-node destination-node"><div className="country-pin"><MapPin size={16}/></div><strong>{s.destination}</strong><span>Destination</span></div></div><div className="route-caption">Your package is being tracked from {s.origin} to {s.destination}.</div></div>}
